function loadOwnerUsers(){
  if(!isFullAccessRole(currentUserProfile?.role))return;
  usersDb.on("value",snap=>{
    const users=snap.val()||{};
    const updates={};
    Object.entries(users).forEach(([uid,user])=>{
      const role=normalizeRole(user.role);
      if(!isFullAccessRole(role) && user.chatAccessManual!==true && user.permissions?.chat===true){
        updates[`${uid}/permissions/chat`]=false;
        updates[`${uid}/chatAccessManual`]=false;
        updates[`${uid}/updatedAt`]=firebase.database.ServerValue.TIMESTAMP;
      }
    });
    if(Object.keys(updates).length){
      usersDb.update(updates).catch(console.error);
    }
    renderOwnerUsers(users);
  });
}
