function loadNotesFromFirebase(){
  notesDb.orderByChild("updatedAt").on("value", snapshot => {
    const data = snapshot.val() || {};

    const migrateUpdates = {};
    Object.entries(data).forEach(([id, note]) => {
      const currentCategory = (note.category || "PK CS").trim();
      const noteTime = Number(note.updatedAt || 0);
      const isOldExistingNote = !noteTime || noteTime <= NOTE_CATEGORY_MIGRATION_CUTOFF;
      if(!note.category || (isOldExistingNote && currentCategory !== "PK CS")){
        note.category = "PK CS";
        migrateUpdates[`${id}/category`] = "PK CS";
      }
      // Beri background comic acak SEKALI untuk note lama yang belum punya comicBg.
      if(!validComicBg(note.comicBg)){
        note.comicBg = randomComicBg();
        migrateUpdates[`${id}/comicBg`] = note.comicBg;
      }
    });
    if(Object.keys(migrateUpdates).length){
      notesDb.update(migrateUpdates).catch(error => console.error(error));
    }

    notepadData = Object.values(data).sort((a, b) => {
      const ao = Number.isFinite(Number(a.order)) ? Number(a.order) : null;
      const bo = Number.isFinite(Number(b.order)) ? Number(b.order) : null;
      if(ao !== null && bo !== null) return ao - bo;
      if(ao !== null) return -1;
      if(bo !== null) return 1;
      return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    renderNotes();
  }, error => {
    console.error(error);
    showToast("Gagal memuat catatan Firebase");
  });
}

