    document.addEventListener("click",e=>{if(!e.target.classList.contains("color-dot")&&!e.target.classList.contains("icon-btn"))document.querySelectorAll(".color-popover").forEach(p=>p.classList.remove("show"))});
    noteList?.addEventListener("dragstart",e=>{
      if(!noteMoveMode)return;
      const card=e.target.closest(".note-card");
      if(!card)return;
      draggedNoteId=card.dataset.id;
      card.classList.add("dragging");
      e.dataTransfer.effectAllowed="move";
      e.dataTransfer.setData("text/plain",draggedNoteId);
    });

    noteList?.addEventListener("dragover",e=>{
      if(!noteMoveMode||!draggedNoteId)return;
      e.preventDefault();
      e.dataTransfer.dropEffect="move";

      const target=e.target.closest(".note-card");
      if(!target||target.dataset.id===draggedNoteId)return;

      const cards=[...noteList.querySelectorAll(".note-card")];
      const dragged=cards.find(card=>card.dataset.id===draggedNoteId);
      if(!dragged)return;

      document.querySelectorAll("#page-notepad .note-card.drop-target").forEach(card=>card.classList.remove("drop-target"));
      target.classList.add("drop-target");

      // Pindahkan DOM secara LANGSUNG. Jadi posisi yang terlihat saat drag = posisi yang akan disimpan.
      const currentCards=[...noteList.querySelectorAll(".note-card")];
      const fromIndex=currentCards.indexOf(dragged);
      const targetIndex=currentCards.indexOf(target);
      if(fromIndex<0||targetIndex<0)return;

      if(fromIndex<targetIndex){
        target.insertAdjacentElement("afterend",dragged);
      }else{
        target.insertAdjacentElement("beforebegin",dragged);
      }
    });

    noteList?.addEventListener("drop",async e=>{
      if(!noteMoveMode||!draggedNoteId)return;
      e.preventDefault();

      applyVisibleDomOrderToData();
      document.querySelectorAll("#page-notepad .note-card.drop-target").forEach(card=>card.classList.remove("drop-target"));

      // Simpan SETIAP selesai drop supaya tidak bisa kembali/ngacak karena render Firebase.
      const ok=await saveNoteOrderToFirebase(false);
      if(ok){
        showToast("Posisi dipindahkan sesuai urutan");
      }
    });

    noteList?.addEventListener("dragend",()=>{
      document.querySelectorAll("#page-notepad .note-card.dragging,#page-notepad .note-card.drop-target").forEach(card=>card.classList.remove("dragging","drop-target"));
      draggedNoteId=null;
    });

