    function addNewDomain(){
      const rawValue=String(newDomainInput?.value||"");
      const inputDomains=[...new Set(
        rawValue
          .split(/[\n,;\t ]+/)
          .map(normalizeDomain)
          .filter(Boolean)
      )];

      if(!inputDomains.length){
        showToast("Masukkan domain terlebih dahulu");
        return;
      }

      const existingDomains=new Set(domainData.map(item=>item.domain));
      const newDomains=inputDomains.filter(domain=>!existingDomains.has(domain));
      const duplicateCount=inputDomains.length-newDomains.length;

      if(!newDomains.length){
        showToast("Semua domain sudah ada");
        return;
      }

      const now=Date.now();
      const newItems=newDomains.map((domain,index)=>({
        id:`d${now}_${index}`,
        domain,
        status:"wait",
        updatedAt:now
      }));

      domainData=[...newItems,...domainData];
      saveDomainData();
      renderDomainChecker();
      closeDomainModal();

      const duplicateText=duplicateCount?` (${duplicateCount} duplikat dilewati)`:"";
      showToast(`${newDomains.length} domain berhasil ditambahkan${duplicateText}`);
    }
