    const PKCS_STORAGE_KEY="kerjaboss_pkcs_v1";
    const pkcsSearchInput=document.getElementById("pkcsSearchInput"),pkcsList=document.getElementById("pkcsList"),pkcsResult=document.getElementById("pkcsResult"),pkcsAddBtn=document.getElementById("pkcsAddBtn"),pkcsEditBtn=document.getElementById("pkcsEditBtn"),pkcsDeleteBtn=document.getElementById("pkcsDeleteBtn"),pkcsCopyBtn=document.getElementById("pkcsCopyBtn"),pkcsCopySuccess=document.getElementById("pkcsCopySuccess"),pkcsModal=document.getElementById("pkcsModal"),pkcsModalTitle=document.getElementById("pkcsModalTitle"),pkcsEditId=document.getElementById("pkcsEditId"),pkcsKeywordInput=document.getElementById("pkcsKeywordInput"),pkcsContentInput=document.getElementById("pkcsContentInput"),pkcsSaveBtn=document.getElementById("pkcsSaveBtn"),pkcsCloseBtn=document.getElementById("pkcsCloseBtn"),pkcsCancelBtn=document.getElementById("pkcsCancelBtn"),pkcsImportSheetBtn=document.getElementById("pkcsImportSheetBtn"),pkcsImportStatus=document.getElementById("pkcsImportStatus"),pkcsReadyBadge=document.getElementById("pkcsReadyBadge");
    let pkcsData=[],pkcsSelectedId=null,pkcsLockedId=null;
    const pkcsDefaults=[
      {id:"pk1",keyword:"MANDIRI KE QRIS",content:"Yth, Member Setia. Untuk sementara Deposit via MANDIRI sedang terkendala sehingga untuk sementara kami alihkan ke QRIS dynamic terlebih dahulu.\n\nKami sarankan silakan deposit ke QRIS kami atau memilih rekening antar bank kami yang lain dalam status online dan normal ya bosku."},
      {id:"pk2",keyword:"CARA MAIN BBFS",content:"Silakan masukkan isi PK CARA MAIN BBFS melalui tombol Edit."},
      {id:"pk3",keyword:"BBFS ADALAH",content:"Silakan masukkan isi PK BBFS ADALAH melalui tombol Edit."}
    ];
    const pkCsDb=firebase.database().ref("pkCsKerjaBoss");
    let pkcsMigrating=false;
    function pkcsLocalBackup(){
      try{localStorage.setItem(PKCS_STORAGE_KEY,JSON.stringify(pkcsData))}catch(e){console.warn("Backup lokal PK gagal",e)}
    }
    function pkcsReadLocal(){
      try{
        const saved=JSON.parse(localStorage.getItem(PKCS_STORAGE_KEY)||"null");
        return Array.isArray(saved)&&saved.length?saved:null;
      }catch(e){return null}
    }
    function pkcsLoad(){
      pkCsDb.on("value",async snapshot=>{
        const data=snapshot.val()||{};
        const firebaseItems=Object.values(data);
        if(!firebaseItems.length&&!pkcsMigrating){
          pkcsMigrating=true;
          const source=pkcsReadLocal()||pkcsDefaults;
          const updates={};
          source.forEach((item,index)=>{
            const id=String(item.id||(`pk_${Date.now()}_${index}`));
            updates[id]={...item,id,updatedAt:item.updatedAt||Date.now()-index};
          });
          try{
            await pkCsDb.update(updates);
            showToast(pkcsReadLocal()?"Data PK lama dipindahkan ke Firebase":"Data awal PK disimpan ke Firebase");
          }catch(error){
            console.error(error);
            pkcsData=source;
            pkcsSelectedId=null;
            pkcsRender(false);
            showToast("Gagal menghubungkan PK CS ke Firebase");
          }finally{pkcsMigrating=false}
          return;
        }
        pkcsData=firebaseItems.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
        pkcsLocalBackup();
        if(pkcsSelectedId&&!pkcsData.some(x=>x.id===pkcsSelectedId))pkcsSelectedId=null;
        if(pkcsLockedId&&!pkcsData.some(x=>x.id===pkcsLockedId))pkcsLockedId=null;
        pkcsRender(false);
      },error=>{
        console.error(error);
        pkcsData=pkcsReadLocal()||[...pkcsDefaults];
        pkcsSelectedId=null;
        pkcsLockedId=null;
        pkcsRender(false);
        showToast("Gagal memuat PK dari Firebase");
      });
    }
    async function pkcsSaveFirebase(item){
      try{await pkCsDb.child(item.id).set(item);return true}
      catch(error){console.error(error);showToast("Gagal menyimpan PK ke Firebase");return false}
    }
    async function pkcsDeleteFirebase(id){
      try{await pkCsDb.child(id).remove();return true}
      catch(error){console.error(error);showToast("Gagal menghapus PK dari Firebase");return false}
    }
    function pkcsEscape(t){return String(t||"").replace(/[&<>"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]))}
    function pkcsNormalize(t){return String(t||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
    function pkcsGetMatches(query){
      const normalizedQuery=pkcsNormalize(query);
      const terms=normalizedQuery.split(/\s+/).filter(Boolean);
      if(!terms.length)return [];

      /*
        Pencarian hanya membaca JUDUL / KATA KUNCI.
        Isi template tidak ikut dicari agar hasil tidak menampilkan
        template lain yang kebetulan memiliki kata serupa di dalam isi.
      */
      return pkcsData.filter(item=>{
        const keyword=pkcsNormalize(item.keyword);
        return terms.every(term=>keyword.includes(term));
      }).sort((a,b)=>{
        const ak=pkcsNormalize(a.keyword);
        const bk=pkcsNormalize(b.keyword);

        const aExact=ak===normalizedQuery?0:1;
        const bExact=bk===normalizedQuery?0:1;
        if(aExact!==bExact)return aExact-bExact;

        const aStart=ak.startsWith(normalizedQuery)?0:1;
        const bStart=bk.startsWith(normalizedQuery)?0:1;
        if(aStart!==bStart)return aStart-bStart;

        const aIndex=ak.indexOf(normalizedQuery);
        const bIndex=bk.indexOf(normalizedQuery);
        if(aIndex!==bIndex)return aIndex-bIndex;

        return ak.localeCompare(bk,"id");
      });
    }
    function pkcsUpdateReadyBadge(){
      if(!pkcsReadyBadge)return;
      pkcsReadyBadge.textContent="DATA SIAP UNTUK DI COPY";
    }
    function pkcsRender(autoSelectTop=false){
      if(!pkcsList)return;
      const q=(pkcsSearchInput?.value||"").trim();
      if(!q){
        pkcsSelectedId=null;
        pkcsLockedId=null;
        pkcsList.innerHTML="";
        pkcsResult.textContent="Ketik kata kunci PK di kolom pencarian untuk menampilkan hasil.";
        pkcsResult.classList.add("pkcs-result-empty");
        pkcsUpdateReadyBadge();
        return;
      }

      const selected=pkcsLockedId?pkcsData.find(x=>x.id===pkcsLockedId):null;
      if(selected){
        pkcsSelectedId=selected.id;
        pkcsList.innerHTML="";
        pkcsResult.textContent=selected.content;
        pkcsResult.classList.remove("pkcs-result-empty");
        pkcsUpdateReadyBadge();
        return;
      }

      const shown=pkcsGetMatches(q);
      if(autoSelectTop||!shown.some(x=>x.id===pkcsSelectedId))pkcsSelectedId=shown[0]?.id||null;
      pkcsList.innerHTML=shown.length?shown.map(x=>`<button type="button" class="pkcs-item ${x.id===pkcsSelectedId?'active':''}" data-id="${x.id}">${pkcsEscape(x.keyword)}</button>`).join(""):`<div class="pkcs-empty">PK tidak ditemukan.<br>Tekan INPUT PK BARU untuk menambahkan.</div>`;
      const active=shown.find(x=>x.id===pkcsSelectedId)||shown[0];
      if(active){
        pkcsSelectedId=active.id;
        pkcsResult.textContent=active.content;
        pkcsResult.classList.remove("pkcs-result-empty");
      }else{
        pkcsSelectedId=null;
        pkcsResult.textContent="PK tidak ditemukan untuk kata kunci tersebut.";
        pkcsResult.classList.add("pkcs-result-empty");
      }
      pkcsUpdateReadyBadge();
    }
    function pkcsOpen(edit=false){const active=pkcsData.find(x=>x.id===pkcsSelectedId);pkcsEditId.value=edit&&active?active.id:"";pkcsKeywordInput.value=edit&&active?active.keyword:"";pkcsContentInput.value=edit&&active?active.content:"";pkcsModalTitle.textContent=edit?"Edit PK":"Input PK Baru";pkcsModal.classList.add("show");setTimeout(()=>pkcsKeywordInput.focus(),60)}
    function pkcsClose(){pkcsModal.classList.remove("show")}
    pkcsSearchInput?.addEventListener("input",()=>{pkcsLockedId=null;pkcsRender(true)});
    pkcsList?.addEventListener("click",e=>{const b=e.target.closest(".pkcs-item");if(!b)return;const active=pkcsData.find(x=>x.id===b.dataset.id);if(!active)return;pkcsSelectedId=active.id;pkcsLockedId=active.id;pkcsSearchInput.value=active.keyword;pkcsRender(false)});
    pkcsAddBtn?.addEventListener("click",()=>pkcsOpen(false));pkcsEditBtn?.addEventListener("click",()=>{if(!pkcsSelectedId)return showToast("Pilih PK terlebih dahulu");pkcsOpen(true)});
    pkcsSaveBtn?.addEventListener("click",async()=>{
      const keyword=pkcsKeywordInput.value.trim(),content=pkcsContentInput.value.trim();
      if(!keyword||!content)return showToast("Kata kunci dan isi PK wajib diisi");
      const oldId=pkcsEditId.value;
      const item=oldId
        ? {...(pkcsData.find(x=>x.id===oldId)||{}),id:oldId,keyword,content,updatedAt:Date.now()}
        : {id:"pk_"+Date.now(),keyword,content,updatedAt:Date.now()};
      pkcsSaveBtn.disabled=true;
      pkcsSaveBtn.textContent="Menyimpan...";
      const ok=await pkcsSaveFirebase(item);
      pkcsSaveBtn.disabled=false;
      pkcsSaveBtn.textContent="Simpan PK";
      if(!ok)return;
      pkcsSelectedId=item.id;
      pkcsLockedId=item.id;
      pkcsClose();
      showToast(oldId?"PK berhasil diperbarui di Firebase":"PK baru berhasil disimpan ke Firebase");
    });
    pkcsDeleteBtn?.addEventListener("click",async()=>{
      if(!pkcsSelectedId)return showToast("Pilih PK terlebih dahulu");
      const active=pkcsData.find(x=>x.id===pkcsSelectedId);
      if(!active||!confirm(`Hapus PK “${active.keyword}”?`))return;
      const deletedId=pkcsSelectedId;
      pkcsDeleteBtn.disabled=true;
      const ok=await pkcsDeleteFirebase(deletedId);
      pkcsDeleteBtn.disabled=false;
      if(!ok)return;
      pkcsSelectedId=null;
      pkcsLockedId=null;
      showToast("PK berhasil dihapus dari Firebase");
    });
    function showPkcsCopySuccess(){
      if(pkcsCopySuccess){
        pkcsCopySuccess.classList.remove("show");
        void pkcsCopySuccess.offsetWidth;
        pkcsCopySuccess.classList.add("show");
        setTimeout(()=>pkcsCopySuccess.classList.remove("show"),900);
      }
      if(pkcsCopyBtn){
        const originalText=pkcsCopyBtn.dataset.originalText||pkcsCopyBtn.textContent;
        pkcsCopyBtn.dataset.originalText=originalText;
        pkcsCopyBtn.classList.add("success");
        pkcsCopyBtn.textContent="Berhasil Dicopy";
        setTimeout(()=>{
          pkcsCopyBtn.classList.remove("success");
          pkcsCopyBtn.textContent=originalText;
        },1100);
      }
    }

    async function pkcsCopyActive(){
      const active=pkcsData.find(x=>x.id===pkcsSelectedId);
      if(!active)return showToast("Pilih PK terlebih dahulu");
      try{
        await navigator.clipboard.writeText(active.content);
        showPkcsCopySuccess();
        showToast("Isi PK berhasil dicopy");
      }catch(e){
        const ta=document.createElement("textarea");
        ta.value=active.content;
        ta.style.position="fixed";
        ta.style.opacity="0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        ta.remove();
        showPkcsCopySuccess();
        showToast("Isi PK berhasil dicopy");
      }
    }
    pkcsCopyBtn?.addEventListener("click",pkcsCopyActive);
    document.addEventListener("keydown",e=>{
      if(!(e.altKey&&e.key.toLowerCase()==="c"))return;
      const pkcsPage=document.getElementById("page-pk-cs");
      if(!pkcsPage?.classList.contains("active")||pkcsModal?.classList.contains("show"))return;
      e.preventDefault();
      pkcsCopyActive();
    });
    pkcsCloseBtn?.addEventListener("click",pkcsClose);pkcsCancelBtn?.addEventListener("click",pkcsClose);pkcsModal?.addEventListener("click",e=>{if(e.target===pkcsModal)pkcsClose()});
    const PKCS_SHEET_CSV_URL="https://docs.google.com/spreadsheets/d/1_EcGXsjxv_iMbk4Vyg8YimzQyj-ymayWe6nNS1ezHc8/gviz/tq?tqx=out:csv&gid=1081718576";
    function pkcsParseCsv(text){
      const rows=[];let row=[],cell="",quoted=false;
      for(let i=0;i<text.length;i++){
        const ch=text[i],next=text[i+1];
        if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;continue}
        if(ch==='"'){quoted=!quoted;continue}
        if(ch===','&&!quoted){row.push(cell);cell="";continue}
        if((ch==='\n'||ch==='\r')&&!quoted){
          if(ch==='\r'&&next==='\n')i++;
          row.push(cell);cell="";
          if(row.some(v=>String(v).trim()!==""))rows.push(row);
          row=[];continue;
        }
        cell+=ch;
      }
      row.push(cell);if(row.some(v=>String(v).trim()!==""))rows.push(row);
      return rows;
    }
    async function pkcsImportGoogleSheet(){
      if(!pkcsImportSheetBtn)return;
      pkcsImportSheetBtn.disabled=true;
      pkcsImportSheetBtn.textContent="MENGAMBIL DATA...";
      if(pkcsImportStatus)pkcsImportStatus.textContent="Membaca kolom A dan B dari Google Sheet...";
      try{
        const response=await fetch(PKCS_SHEET_CSV_URL,{cache:"no-store"});
        if(!response.ok)throw new Error("HTTP "+response.status);
        const text=await response.text();
        const rows=pkcsParseCsv(text);
        const existingByKeyword=new Map(pkcsData.map(x=>[pkcsNormalize(x.keyword),x]));
        const updates={};let added=0,updated=0,skipped=0;
        rows.forEach((row,index)=>{
          const keyword=String(row[0]||"").trim();
          const content=String(row[1]||"").trim();
          if(!keyword||!content){skipped++;return}
          const normalized=pkcsNormalize(keyword);
          if(index===0&&(/kata.?kunci|keyword|judul/i.test(keyword))&&(/isi|content|pk/i.test(content))){skipped++;return}
          const old=existingByKeyword.get(normalized);
          const id=old?.id||("pk_sheet_"+Date.now()+"_"+index);
          updates[id]={id,keyword,content,updatedAt:Date.now()+index};
          if(old)updated++;else added++;
        });
        if(!Object.keys(updates).length)throw new Error("Tidak ada data valid pada kolom A dan B");
        await pkCsDb.update(updates);
        const msg=`Import selesai: ${added} baru, ${updated} diperbarui, ${skipped} dilewati.`;
        if(pkcsImportStatus)pkcsImportStatus.textContent=msg;
        showToast(msg);
      }catch(error){
        console.error(error);
        const msg="Import gagal. Pastikan Google Sheet dapat dilihat oleh siapa saja yang memiliki link dan tab PK memakai gid 1081718576.";
        if(pkcsImportStatus)pkcsImportStatus.textContent=msg;
        showToast("Gagal import Google Sheet");
      }finally{
        pkcsImportSheetBtn.disabled=false;
        pkcsImportSheetBtn.textContent="⇩ IMPORT GOOGLE SHEET";
      }
    }
    pkcsImportSheetBtn?.addEventListener("click",()=>{
      if(confirm("Import semua data kolom A sebagai kata kunci dan kolom B sebagai isi PK ke Firebase? Data dengan kata kunci sama akan diperbarui."))pkcsImportGoogleSheet();
    });
    function pkcsUpdateClock(){const d=new Date();const time=new Intl.DateTimeFormat("id-ID",{timeZone:"Asia/Jakarta",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:false}).format(d).replace(/\./g,":");const date=new Intl.DateTimeFormat("id-ID",{timeZone:"Asia/Jakarta",weekday:"long",day:"2-digit",month:"long",year:"numeric"}).format(d);const t=document.getElementById("pkcsClockTime"),dt=document.getElementById("pkcsClockDate");if(t)t.textContent=time;if(dt)dt.textContent=date;const parts=time.split(":").map(Number),h=parts[0]||0,m=parts[1]||0,s=parts[2]||0;const hour=document.querySelector(".pkx-clock-hand.hour"),minute=document.querySelector(".pkx-clock-hand.minute"),second=document.querySelector(".pkx-clock-hand.second");if(hour)hour.style.transform=`translateX(-50%) rotate(${(h%12)*30+m*.5}deg)`;if(minute)minute.style.transform=`translateX(-50%) rotate(${m*6+s*.1}deg)`;if(second)second.style.transform=`translateX(-50%) rotate(${s*6}deg)`}setInterval(pkcsUpdateClock,1000);pkcsUpdateClock();pkcsLoad();
